<?php
/**
 * Starts Tranzly: every class, the boot calls, the premium layer's licence, the AI core and the
 * admin kit.
 *
 * Read by bootstrap.php through Cli_Start::start(): at once, or — in a WP-CLI command — on WP-CLI's
 * `after_wp_load`, with every already-fired action replayed (class-cli-start.php, stage PERF3).
 *
 * @package ZinnDigital\Tranzly
 */

declare( strict_types = 1 );

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

require_once __DIR__ . '/core/class-boot.php';
require_once __DIR__ . '/functions.php';
// HOSTDISC — the hosting-customer Pro discount card (generated by wp/bin/build-promo.php).
require_once __DIR__ . '/class-pro-discount.php';
require_once __DIR__ . '/seo/class-head.php';
require_once __DIR__ . '/seo/class-robots.php';
require_once __DIR__ . '/seo/class-seo.php';
require_once __DIR__ . '/integrations/load.php';
// Lane PLUGIN-MCP: the abilities (WordPress Abilities API) and this site's own MCP server, through
// the shared MCP kit (wp/packages/zinn-mcp-kit) and the bundled WordPress MCP adapter.
require_once __DIR__ . '/mcp-kit/load.php';

/*
 * ⛔⛔ THE PREMIUM LAYER, WHEN IT SHIPS, REGISTERS ITS LICENCE FIRST, SO EVERY BOOT BELOW SEES IT.
 *
 * The free package drops the whole premium-only directory, so nothing here runs there, and the
 * free plugin itself never asks the licensing SDK anything (WordPress.org guideline 5). The
 * directory name is assembled from two halves so the premium-only token never appears in a file
 * that ships in the free package (CONTRACT §3, docs/adr/0032).
 */
$tranzly_premium_entry = __DIR__ . '/pro_' . '_premium_only/class-pro.php'; // phpcs:ignore Generic.Strings.UnnecessaryStringConcat.Found -- deliberate split, see above.
if ( is_readable( $tranzly_premium_entry ) ) {
	require_once $tranzly_premium_entry;
	\ZinnDigital\Tranzly\Pro\Pro::licence();
}
unset( $tranzly_premium_entry );

\ZinnDigital\Tranzly\Plugin::boot();
\ZinnDigital\Tranzly\Mcp\Abilities::boot();

/*
 * The shared AI core (wp/packages/zinn-ai-core, rendered into ai-core/ by wp/bin/build-ai-core.php).
 * If another plugin on the site carries its own copy, the copies agree on one settings screen and
 * one set of keys by themselves; see ai-core/class-core.php.
 */
require_once __DIR__ . '/ai-core/load.php';
\ZinnDigital\Tranzly\AiCore\Core::boot(
	array(
		'slug' => 'tranzly',
		'name' => 'Tranzly',
		'pro'  => static fn(): bool => \ZinnDigital\Tranzly\Core\Edition::pro(),
	)
);

/*
 * The shared admin kit (wp/packages/zinn-admin-kit, rendered into admin-kit/ by
 * wp/bin/build-admin-kit.php): the shell around the settings screen — overview, plans, add-ons,
 * help and support, the setup wizard. Our own screens only; it adds nothing to other admin pages.
 */
require_once __DIR__ . '/admin-kit/load.php';
\ZinnDigital\Tranzly\AdminKit\Kit::boot(
	array(
		'slug'           => 'tranzly',
		'name'           => 'Tranzly',
		'version'        => TRANZLY_VERSION,
		'fs'             => 'tranzly_fs',
		'menu_slug'      => \ZinnDigital\Tranzly\Admin::SLUG,
		'rest_namespace' => \ZinnDigital\Tranzly\Rest::NAMESPACE,
		'file'           => TRANZLY_FILE,
	)
);

// The premium layer's features, when it is running (registered above, before the core booted).
if ( class_exists( '\\ZinnDigital\\Tranzly\\Pro\\Pro', false ) && \ZinnDigital\Tranzly\Core\Edition::pro() ) {
	\ZinnDigital\Tranzly\Pro\Pro::boot();
}
